-- Starter kit: the club site's identity, reduced to what the task platform
-- reads. On ruetcs.org these tables and functions already exist, with more
-- columns and their own policies; the names here match them, so policies an
-- Entry writes against them port unchanged. Do not edit this file.

-- Officers (super admins and moderators).
create table public.admins (
  email text primary key check (email = lower(btrim(email)) and email like '%@%'),
  role text not null check (role in ('super_admin', 'moderator')),
  active boolean not null default true
);

-- Paid society Members. Every Learner is one.
create table public.members (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  roll text not null unique,
  department text not null,
  series text not null,
  email text not null unique check (email = lower(btrim(email))),
  phone text
);

-- Deny-all until a policy says otherwise. The two functions below read these
-- tables as their owner, so they work without any policy.
alter table public.admins enable row level security;
alter table public.members enable row level security;

-- An active Officer is signed in. Identical to ruetcs.org.
create function public.is_admin() returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.admins
    where active and email = lower(auth.jwt() ->> 'email')
  )
$$;

-- The Member who is signed in, or null. Added to ruetcs.org at merge time.
create function public.viewer_member_id() returns uuid
language sql stable security definer set search_path = ''
as $$
  select id from public.members
  where email = lower(auth.jwt() ->> 'email')
  limit 1
$$;
